from robot.api import logger

ta_egate_connections_registry = {}


def add_to_registry(egate_id, egate_host, egate_port):
    """

    :param egate_id:
    :param egate_host:
    :param egate_port:
    :return:
    """
    if str(egate_id) in list(ta_egate_connections_registry.keys()):
        raise KeyError('egate_id = {} already exist. Please use different one.'.format(egate_id))
    else:
        ta_egate_connections_registry[str(egate_id)] = {
            "host": egate_host,
            "port": egate_port
        }
    logger.info('EGATE connections registry: {}'.format(ta_egate_connections_registry))


def remove_from_registry(egate_id):
    """

    :param egate_id:
    :return:
    """
    if str(egate_id) in list(ta_egate_connections_registry.keys()):
        del ta_egate_connections_registry[str(egate_id)]
    logger.info('EGATE connections registry: {}'.format(ta_egate_connections_registry))


def get_ta_egate_connection(egate_id):
    """

    :param egate_id:
    :return:
    """
    return ta_egate_connections_registry[str(egate_id)]
